clear;
clc;
close all;

%% Step 1: Create synthetic robot telemetry dataset

time = 0:0.1:60; % seconds

% Velocity data
velocity = 2 + 0.5*sin(0.4*time) + 0.2*randn(size(time));

% Add stop events
velocity(150:180) = 0.1;
velocity(420:450) = 0.1;

% Steering angle data in degrees
steering = 15*sin(0.3*time) + 5*randn(size(time));

% Add steering spikes
steering(250:260) = 45;
steering(500:510) = -45;

%% Step 2: Smooth noisy signals

windowSize = 10;

smoothVelocity = movmean(velocity, windowSize);
smoothSteering = movmean(steering, windowSize);

% Compute average speed
averageSpeed = mean(smoothVelocity);

% Detect stop events
stopEvents = smoothVelocity < 0.3;
numberOfStopEvents = sum(diff([0 stopEvents]) == 1);

% Detect turning events
turningEvents = abs(smoothSteering) > 20;
numberOfTurningEvents = sum(diff([0 turningEvents]) == 1);

% Detect steering spikes
steeringSpikes = abs(steering) > 35;
numberOfSteeringSpikes = sum(diff([0 steeringSpikes]) == 1);

%% Step 3: Visualizations

% Velocity vs time
figure; %[output:1cf565c7]
plot(time, velocity, 'LineWidth', 1); %[output:1cf565c7]
hold on; %[output:1cf565c7]
plot(time, smoothVelocity, 'LineWidth', 2); %[output:1cf565c7]
grid on; %[output:1cf565c7]
xlabel('Time (seconds)'); %[output:1cf565c7]
ylabel('Velocity'); %[output:1cf565c7]
title('Velocity vs Time'); %[output:1cf565c7]
legend('Raw Velocity', 'Smoothed Velocity'); %[output:1cf565c7]

% Steering vs time
figure; %[output:270e148c]
plot(time, steering, 'LineWidth', 1); %[output:270e148c]
hold on; %[output:270e148c]
plot(time, smoothSteering, 'LineWidth', 2); %[output:270e148c]
grid on; %[output:270e148c]
xlabel('Time (seconds)'); %[output:270e148c]
ylabel('Steering Angle (degrees)'); %[output:270e148c]
title('Steering Angle vs Time'); %[output:270e148c]
legend('Raw Steering', 'Smoothed Steering'); %[output:270e148c]

% Scatter steering vs speed
figure; %[output:57423943]
scatter(smoothVelocity, smoothSteering); %[output:57423943]
grid on; %[output:57423943]
xlabel('Velocity'); %[output:57423943]
ylabel('Steering Angle (degrees)'); %[output:57423943]
title('Steering vs Speed'); %[output:57423943]

% Histogram of speed
figure; %[output:8b478100]
histogram(smoothVelocity); %[output:8b478100]
grid on; %[output:8b478100]
xlabel('Velocity'); %[output:8b478100]
ylabel('Frequency'); %[output:8b478100]
title('Histogram of Speed'); %[output:8b478100]

%% Step 4: Driving quality score

% Metric 1: average speed score
speedScore = min(averageSpeed / 2.5, 1) * 40;

% Metric 2: smoothness score
velocitySmoothness = std(diff(smoothVelocity));
smoothnessScore = max(0, 30 - velocitySmoothness * 20);

% Metric 3: steering spike penalty
steeringPenalty = numberOfSteeringSpikes * 5;

% Final quality score out of 100
qualityScore = speedScore + smoothnessScore + 30 - steeringPenalty;

% Keep score between 0 and 100
qualityScore = max(0, min(100, qualityScore));

%% Display results

disp("Average speed:"); %[output:7f229a0a]
disp(averageSpeed); %[output:3e9bfa58]

disp("Number of stop events:"); %[output:49050f97]
disp(numberOfStopEvents); %[output:90657768]

disp("Number of turning events:"); %[output:652e756e]
disp(numberOfTurningEvents); %[output:9f4bc58b]

disp("Number of steering spikes:"); %[output:33cb9656]
disp(numberOfSteeringSpikes); %[output:93e79123]

disp("Driving quality score out of 100:"); %[output:3e3bf083]
disp(qualityScore); %[output:16eaf67a]

disp("Interpretation:"); %[output:394dab29]
disp("A higher score means smoother driving, fewer steering spikes, and better speed consistency."); %[output:891269a9]
disp("Stop events show when the robot slowed down or stopped."); %[output:5991c058]
disp("Turning events show when the steering angle became large."); %[output:52427923]

